pragma solidity ^0.8.10;
contract T {mapping(uint=>uint) values;
function rawSet(uint key,uint v) external {assembly{mstore(0,key)mstore(32,0)sstore(keccak256(0,64),v)}}
function typedSet(uint key,uint v) external {values[key]=v;}
function typedGet(uint key) external view returns(uint){return values[key];}
function rawGet(uint key) external view returns(uint v){assembly{mstore(0,key)mstore(32,0)v:=sload(keccak256(0,64))}}
}
contract C {T t;constructor(address a){t=T(a);}
function a() external{t.rawSet(0,1);require(t.typedGet(0)==1);}
function b() external{t.typedSet(0,1);require(t.rawGet(0)==1);}}

pragma solidity ^0.8.10;
contract T {function set(int key,int value) external {assembly{sstore(key,value)}}
function get(uint key) external view returns(uint value){assembly{value:=sload(key)}}}
contract C {T t;constructor(address a){t=T(a);}
function a() external{t.set(-1,7);require(t.get(type(uint256).max)==7);}
function b() external{t.set(1,-1);require(t.get(1)==type(uint256).max);}}

pragma solidity ^0.8.10;
contract T {struct A {uint x;} struct B {uint y;}
function one() internal pure returns(A storage s){assembly{s.slot:=3840}}
function two() internal pure returns(B storage s){assembly{s.slot:=3840}}
function put() external {one().x=1;}
function get() external view returns(uint){return two().y;}}
contract C {T t;constructor(address a){t=T(a);}
function a() external{t.put();require(t.get()==1);}
function b() external{t.put();require(t.get()==0);}}
